<?php
if(!defined('TIVOLI_PURCHASE_CORRECTIONS')){http_response_code(403);exit;}
require_once dirname(__DIR__).'/bootstrap/stays.php';
use Tivoli\Service\PurchaseCorrectionService;use Tivoli\Service\FinanceAttachment;use Tivoli\Domain\Stay\StayRules as R;
$s=new PurchaseCorrectionService(access_service());$actor=(int)$user['id'];$owner=$s->owner($actor);$id=max(0,filter_var($_GET['id']??0,FILTER_VALIDATE_INT)?:0);$sourceId=max(0,filter_var($_GET['source_id']??0,FILTER_VALIDATE_INT)?:0);$sourceType=is_string($_GET['source_type']??null)?$_GET['source_type']:'';$page=is_string($_GET['page']??null)?$_GET['page']:'sources';if(!in_array($page,['sources','requests','review','log','notice'],true))$page='sources';$form=is_string($_GET['form']??null)?$_GET['form']:'';$before=max(0,filter_var($_GET['before']??0,FILTER_VALIDATE_INT)?:0);
$values=$_SERVER['REQUEST_METHOD']==='POST'?array_filter($_POST,'is_string'):[];$operationKey=$_SERVER['REQUEST_METHOD']==='POST'?($values['operation_key']??''):bin2hex(random_bytes(16));$error='';$case=null;$source=null;$rows=[];$next=0;$files=[];
try{
 $s->permit($actor);
 if($_SERVER['REQUEST_METHOD']==='POST'){access_check_csrf();$input=$values;if(isset($_FILES['evidence_file'])&&($_FILES['evidence_file']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE)$input['_evidence']=FinanceAttachment::uploaded($_FILES['evidence_file']);$action=$values['action']??'';if($action==='return'&&($values['owner_decision']??'')==='reject')$action='reject';$out=$s->execute($actor,$action,$input,$operationKey);$_SESSION['pc_notice']='Linked action recorded.';header('Location: '.pc_url($out['id']?['id'=>$out['id']]:['source_type'=>$out['source_type'],'source_id'=>$out['source_id']]).'#purchase-correction-action');exit;}
 $data=access_service()->transaction(function()use($s,$actor,$owner,$id,$sourceId,$sourceType,$page,$before,$form){
  if($id){$c=$s->detail($actor,$id);if($page==='notice'&&$c['status']!=='posted')throw new RuntimeException('Only posted corrections have adjustment notices.');if($form==='revise'&&($c['status']!=='returned'||(int)$c['root']['actor_id']!==$actor))throw new \Tivoli\Security\PermissionDenied('Only requester may revise a returned correction.');return ['case'=>$c,'source'=>$c['live']];}
