  if($page!=='sources')return $s->register($actor,$page,$before);
  $r=access_service()->repo;$where=$owner?'':' AND e.actor_id=?';$params=$owner?[]:[$actor];if($before){$where.=' AND e.id<?';$params[]=$before;}$rows=$r->run("SELECT e.id,e.kind,e.actor_id,e.created_at,u.name actor_name,e.payload FROM finance_events e JOIN users u ON u.id=e.actor_id WHERE ((e.kind IN ('purchase_requested','purchase_unapproved') AND EXISTS(SELECT 1 FROM finance_events p WHERE p.kind='purchase_posted' AND p.target_type='purchase' AND p.target_id=CAST(e.id AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_unicode_ci)) OR (e.kind='provider_requested' AND EXISTS(SELECT 1 FROM finance_events p WHERE p.kind='request_approved' AND p.target_type='request' AND p.target_id=CAST(e.id AS CHAR CHARACTER SET utf8mb4) COLLATE utf8mb4_unicode_ci)))".$where.' ORDER BY e.id DESC LIMIT 51',$params)->fetchAll();$more=count($rows)>50;if($more)array_pop($rows);return ['rows'=>$rows,'next'=>$more?(int)end($rows)['id']:0];
 });extract($data,EXTR_OVERWRITE);access_service()->audit($actor,'purchase_correction.viewed','purchase_correction',$id?(string)$id:null,'succeeded',['page'=>$page]);
}catch(Throwable $e){$error=access_error($e);http_response_code($e instanceof \Tivoli\Security\PermissionDenied||http_response_code()===403?403:($e instanceof PDOException?503:400));if(!in_array(http_response_code(),[403,503],true))try{if($id){$case=$s->detail($actor,$id);$source=$case['live'];}elseif($sourceId)$source=$s->source($actor,$sourceType,$sourceId);}catch(Throwable $ignored){}
}
if($case)foreach(array_merge([$case['root']],$case['history']) as $e)if(FinanceAttachment::available(access_service(),'purchasecorrection',(int)$e['id']))$files[(int)$e['id']]=true;
