function pc_url(array $q=[]):string{return access_url('financial-corrections.php?'.http_build_query(['area'=>'purchases']+$q));}
function pc_money(int $n):string{return ($n<0?'-':'').'GHS '.R::decimal(abs($n));}
function pc_fields(string $action):void{global $operationKey,$case,$source;foreach(['csrf'=>access_csrf(),'operation_key'=>$operationKey,'action'=>$action]+($case?['id'=>(string)$case['root']['id'],'version'=>$case['version']]:[])+($source?['source_type'=>$source['source_type'],'source_id'=>(string)$source['source_id'],'source_token'=>$source['token']]:[]) as $k=>$v)echo '<input type="hidden" name="'.access_h($k).'" value="'.access_h($v).'">';}
function pc_input(string $label,string $name,string $default='',string $type='text',bool $required=true):void{global $values;echo '<label>'.access_h($label).($required?' *':' (Optional)').'<input name="'.access_h($name).'" type="'.access_h($type).'" value="'.access_h($values[$name]??$default).'"'.($type==='datetime-local'?' step="1"':'').' maxlength="2000"'.($required?' required':'').'></label>';}
function pc_reason(string $default=''):void{global $values;echo '<label>Reason / Verified Evidence *<textarea name="reason" required maxlength="2000" rows="3">'.access_h($values['reason']??$default).'</textarea></label>';}
function pc_check(string $name,string $label):void{echo '<label class="cc-check"><input type="checkbox" name="'.access_h($name).'" value="1" required><span>'.access_h($label).'</span></label>';}
function pc_file(int $id):void{global $files;if(isset($files[$id]))echo '<a href="'.access_h(access_url('finance-evidence.php?kind=purchasecorrection&id='.$id)).'">Download Private Evidence</a>';}
